package com.networkers.notification;
import com.networkers.user.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.time.*;
@Service public class BirthdayNotificationService{private final UserRepository users;private final NotificationService notifications;public BirthdayNotificationService(UserRepository u,NotificationService n){users=u;notifications=n;}@Scheduled(cron="0 5 9 * * *",zone="Asia/Kolkata")public void send(){LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));var members=users.findByRole(Role.USER).stream().filter(u->u.isEnabled()&&!u.isDeleted()).toList();for(User birthday:members)if(birthday.getDateOfBirth()!=null&&birthday.getDateOfBirth().getMonthValue()==today.getMonthValue()&&birthday.getDateOfBirth().getDayOfMonth()==today.getDayOfMonth())for(User recipient:members)notifications.notify(recipient,"Happy Birthday, "+birthday.getFullName()+"!","The Networkers community wishes "+birthday.getFullName()+" a wonderful birthday and a successful year ahead.");}}
